#!/usr/bin/env bash
# Regenerate fixtures/wire/*: bulk images in older (and one mock newer) wire
# formats, derived from the real V32 capture fixtures/bulk_v32.bin and from a
# synthetic byte pattern, by compiling the HISTORICAL firmware bulk_params.h of
# each shipped release (see fixtures/wire/README.md).
#
#   tools/wirecompat/gen_fixtures.sh [path to a WeebLabs/DSPi clone]   (default ~/prog/DSPi)
#
# Host side: only `git show` (headers are extracted into build/, never checked
# in: the firmware is GPL-3.0 and this repo only needs the generated bytes).
# Compiling and running happens in the build container (tools/dev.sh).
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(git -C "$here/.." rev-parse --show-toplevel)"
DSPI="${1:-$HOME/prog/DSPi}"
WORK="$ROOT/build/wirecompat"
OUT="$ROOT/fixtures/wire"
H=firmware/DSPi/bulk_params.h

# tag -> wire version of every shipped firmware release since the V16 break
TAGS=(v1.1.5-beta3:17 v1.1.5-beta4:21 v1.1.5-beta5:24 v1.1.5-beta6:26 v1.1.5:28 v1.1.6-beta3:30 v1.1.6:32)

if [[ "${DSPI_IN_CONTAINER:-}" != 1 ]]; then
  rm -rf "$WORK"; mkdir -p "$WORK" "$OUT"
  for tv in "${TAGS[@]}"; do
    tag="${tv%%:*}"
    mkdir -p "$WORK/$tag"
    git -C "$DSPI" show "$tag:$H" > "$WORK/$tag/bulk_params.h"
    git -C "$DSPI" rev-parse "$tag^{commit}" > "$WORK/$tag/commit"
  done
  exec "$ROOT/tools/dev.sh" "$here/gen_fixtures.sh" "$DSPI"
fi

cd "$WORK"
CFLAGS=(-std=c11 -O1 -Wall -Wextra -Werror -Wno-unused-result)
cc "${CFLAGS[@]}" -I v1.1.6 -I "$here" -c "$here/v32_side.c" -o v32_side.o
: > layouts.txt
for tv in "${TAGS[@]}"; do
  tag="${tv%%:*}"; v="${tv##*:}"
  cc "${CFLAGS[@]}" -DTAG="\"$tag\"" -I "$tag" -I "$here" "$here/hist_side.c" v32_side.o -o "hist_$tag"
  grep -q "define WIRE_FORMAT_VERSION *$v\b" "$tag/bulk_params.h" || { echo "$tag is not V$v" >&2; exit 1; }
  "./hist_$tag" "$ROOT/fixtures/bulk_v32.bin" "$OUT/bulk_v$v.bin" --layout >> layouts.txt
  echo "  commit $(cat "$tag/commit")" >> layouts.txt
  "./hist_$tag" --pattern "$OUT/pattern_v$v.bin"
done
./hist_v1.1.6 "$ROOT/fixtures/bulk_v32.bin" "$OUT/bulk_v33_mock.bin" --newer
cp layouts.txt "$OUT/layouts.txt"
cmp "$OUT/bulk_v32.bin" "$ROOT/fixtures/bulk_v32.bin" && rm "$OUT/bulk_v32.bin" # V32 -> V32 is the identity
(cd "$OUT" && sha256sum ./*.bin | sed 's| \./| |')
